/**
 * Rule: semantics/button-name-only-symbol
 * Satisfies: wcag22:4.1.2, wcag21:4.1.2
 * Spec (Name, Role, Value): https://www.w3.org/TR/WCAG22/#name-role-value
 *
 * > For all user interface components (including but not limited to:
 * > form elements, links and components generated by scripts), the name
 * > and role can be programmatically determined. (SC 4.1.2)
 *
 * Source: https://www.w3.org/TR/WCAG22/#name-role-value
 *
 * Flags `<button>` (and JSX button wrappers, plus `role="button"`)
 * whose computed accessible name is one or two characters drawn
 * entirely from the Unicode punctuation (`\p{P}`) or symbol (`\p{S}`)
 * categories. Canonical shapes:
 *
 *     <button>×</button>          <!-- U+00D7 close button -->
 *     <button>+</button>          <!-- U+002B add control -->
 *     <button>-</button>          <!-- U+002D / hyphen-minus remove -->
 *     <button>?</button>          <!-- U+003F help -->
 *     <button>!</button>          <!-- U+0021 warning / alert -->
 *     <button>×</button>          <!-- multiplication-sign as close -->
 *     <button>›</button>          <!-- U+203A next -->
 *     <button>«</button>          <!-- U+00AB previous -->
 *     <button>→</button>          <!-- U+2192 continue -->
 *     <button>★</button>          <!-- U+2605 favorite -->
 *     <button>♥</button>          <!-- U+2665 heart -->
 *     <button>⏵</button>          <!-- U+23F5 play -->
 *     <button>⏸</button>          <!-- U+23F8 pause -->
 *     <button>…</button>          <!-- U+2026 more / overflow -->
 *
 * In every case AT either announces the codepoint as its Unicode-name
 * punctuation ("multiplication sign", "left-pointing double angle
 * quotation mark") or skips it entirely — neither hands the user any
 * usable action cue. The visual convention (× = close, ? = help,
 * › = next, ⏵ = play) is sighted-only metadata; AT users hear nothing
 * meaningful.
 *
 * This is the button-axis sibling of `navigation/link-name-only-symbol`
 * — same predicate, different host element. Symbol-only buttons slip
 * past `semantics/button-name` because they DO have text content (the
 * glyph itself), so the name-presence check passes. This rule fires on
 * the gap between "no name" and "real text".
 *
 * Detection scope (intentionally tight to keep false positives low):
 *
 *   - applies to `<button>` (any type), `role="button"` on a non-button
 *     element, and JSX `<button>` plus wrapper components mapped via
 *     `nativeWrappers`.
 *   - `<input type="submit|button|reset|image">` is NOT in scope —
 *     those are named via the `value` attribute (or `alt` for image
 *     buttons), and a single-character `value="X"` is far less common
 *     in practice than `<button>X</button>`.
 *   - if `aria-label` (non-empty), `aria-labelledby`, or `title`
 *     (non-empty) is present, the override path supplies a real name —
 *     stay silent.
 *   - if the element itself carries `aria-hidden="true"`, it's been
 *     removed from the a11y tree — silent.
 *   - JSX expression children (`<button>{label}</button>`) are opaque
 *     at static time — silent.
 *   - subtree text excludes `aria-hidden="true"` descendants (no
 *     contribution to the accessible name) and decoration via
 *     `role="presentation"`/`"none"`.
 *   - `<img>` children with non-empty `alt` contribute the alt text as
 *     name material; an `alt="X"` (single letter) on an image is a
 *     separate failure mode owned by `media/alt-text-placeholder`.
 *   - The four named entities the HTML parser does NOT decode
 *     (`&laquo;` `&raquo;` `&lsaquo;` `&rsaquo;`) plus `&times;` are
 *     locally substituted before the codepoint scan. Numeric entities
 *     (`&#171;` `&#xAB;`) are already decoded by the parser.
 */

import { defineRule } from "../../api/plugin.ts";
import {
  findHtmlElementsByTag,
  findJsxElementsForTag,
  getHtmlAttribute,
  getJsxAttributeString,
  hasHtmlAttribute,
  hasJsxAttribute,
  walkHtmlElements,
  walkJsxElements,
} from "../../engine/ast-helpers.ts";
import type {
  HtmlDocument,
  HtmlElement,
  HtmlNode,
  JsxElement,
  JsxNode,
  TsxModule,
} from "../../types/ast.ts";

/**
 * Named-entity shorthands the HTML parser leaves un-decoded (the
 * parser's named-entity table is intentionally tiny — see
 * `src/input/parsers/html.ts` `NAMED_ENTITIES`). Numeric entities
 * (`&#171;`, `&#xAB;`) are decoded upstream; only these named shapes
 * survive as literal `&laquo;`-style strings into the text nodes.
 *
 * Mirrors the table in `navigation/link-name-only-symbol`; kept local
 * (no cross-rule import) per the no-cross-rule-dependencies invariant.
 */
const NAMED_ENTITY_MAP: Readonly<Record<string, string>> = {
  "&laquo;": "«",
  "&raquo;": "»",
  "&lsaquo;": "‹",
  "&rsaquo;": "›",
  "&times;": "×",
  "&plus;": "+",
  "&middot;": "·",
  "&bull;": "•",
};

/**
 * Maximum length (in Unicode codepoints, not UTF-16 code units) of an
 * accessible name we treat as "symbol-only". Two covers paired glyphs
 * ("++", "↑↑", "« «") that some authors use as fast-forward / step
 * controls. Beyond two characters the button almost certainly carries
 * word content (even short ones — "Hi", "OK") and falls outside this
 * rule's scope. Mirrors the link sibling's ceiling.
 */
const MAX_SYMBOL_NAME_LENGTH = 2;

export const rule = defineRule({
  id: "semantics/button-name-only-symbol",
  satisfies: ["wcag22:4.1.2", "wcag21:4.1.2"],
  severity: "warning",
  scope: "node",
  fixClass: "guidance",
  // Opt in: wrapper components declared as rendering `<button>` via the
  // object form of `nativeWrappers` also get checked — mirrors
  // `semantics/button-name`.
  wrapperTreatsAsElement: "button",
  appliesTo: {
    fileExtensions: [".html", ".htm", ".tsx", ".jsx"],
  },
  docs: {
    description:
      "Flags <button> (and JSX button wrappers / role=button) whose computed accessible name is one or two characters drawn entirely from Unicode punctuation/symbol categories — × (close), + (add), - (remove), ? (help), ! (warning), arrows, chevrons, stars, play/pause glyphs. Screen readers announce these as punctuation ('multiplication sign') or skip them, leaving the button with no usable action cue. Add an aria-label naming the action (or include a visually-hidden span inside the button expanding the glyph into words). Sibling of navigation/link-name-only-symbol on the button axis; symbol-only buttons slip past semantics/button-name because the glyph counts as text content.",
    rationale:
      "Assistive technology decides how to announce a button from its accessible name. When the name is one or two punctuation/symbol codepoints, AT either reads the Unicode-category name verbatim ('multiplication sign', 'left-pointing double angle quotation mark') or skips the codepoint entirely — neither outcome tells the user what the button does. The visual convention (× = close, + = add, ? = help, › = next, ★ = favorite, ⏵ = play) is sighted-only metadata; AT users hear nothing meaningful.\n\nThis is the button-axis sibling of `navigation/link-name-only-symbol`. Symbol-only buttons are the canonical false negative of `semantics/button-name`: that rule checks whether the button has *any* text content, and a glyph like `×` or `+` IS text — so the bare-name check passes. The accessible-name predicate this rule applies is stricter: the name must contain a letter or digit somewhere, otherwise AT users get the codepoint pronunciation (or nothing) where the author meant `Close` / `Add` / `Previous`.\n\nSpecifically the matched shapes:\n\n  - One- or two-codepoint accessible names (after collapsing whitespace and decoding the four named entities the HTML parser leaves intact: &laquo; &raquo; &lsaquo; &rsaquo; plus &times;).\n  - Every codepoint must be in Unicode punctuation (\\p{P}) OR symbol (\\p{S}) — letters and digits exit the rule (a letter is real text; a digit might be a step number labeled by surrounding context).\n  - Buttons with aria-label / aria-labelledby / title overrides stay silent (the override is the real accessible name).\n  - Buttons with aria-hidden='true' on themselves are removed from the a11y tree — silent.\n  - JSX expression children (`<button>{label}</button>`) are opaque to static analysis — silent.\n\nDistinct from `semantics/button-name` (which fires only on truly empty buttons / icon-only shells) and from the icon-font path it carries (an `<i class=\"fa-close\">` child with no surrounding text). Symbol-only buttons sit in the gap between those two paths.",
    goodExample: `<button aria-label="Close dialog">×</button>`,
    badExample: `<button>×</button>`,
    normativeQuote:
      "For all user interface components (including but not limited to: form elements, links and components generated by scripts), the name and role can be programmatically determined.",
    references: [
      "https://www.w3.org/TR/WCAG22/#name-role-value",
      "https://www.w3.org/WAI/WCAG22/Techniques/aria/ARIA6",
      "https://www.w3.org/WAI/WCAG22/Techniques/aria/ARIA9",
      "https://www.w3.org/WAI/WCAG22/Techniques/general/G108",
    ],
  },
  check(ctx) {
    if (ctx.language === "html") {
      checkHtml(ctx.ast as HtmlDocument, (v) => ctx.emit(v));
    } else if (
      ctx.language === "tsx" ||
      ctx.language === "jsx" ||
      ctx.language === "ts" ||
      ctx.language === "js"
    ) {
      checkJsx(ctx.ast as TsxModule, ctx.wrappersForElement, (v) => ctx.emit(v));
    }
  },
});

type Emit = (v: {
  severity: "warning";
  location: { filePath: string; line: number; column: number };
  message: string;
  suggestion: string;
}) => void;

// ---------------------------------------------------------------------------
// HTML
// ---------------------------------------------------------------------------

function checkHtml(doc: HtmlDocument, emit: Emit): void {
  for (const button of findHtmlElementsByTag(doc, "button")) {
    checkHtmlElement(button, "button", emit);
  }
  // role="button" on a non-button, non-input element.
  for (const el of walkHtmlElements(doc)) {
    const lowered = el.tagName.toLowerCase();
    if (lowered === "button" || lowered === "input") continue;
    if (getHtmlAttribute(el, "role")?.toLowerCase() !== "button") continue;
    checkHtmlElement(el, `${el.tagName} role="button"`, emit);
  }
}

function checkHtmlElement(el: HtmlElement, subject: string, emit: Emit): void {
  if (getHtmlAttribute(el, "aria-hidden") === "true") return;
  if (hasAccessibleNameOverrideHtml(el)) return;
  const visible = visibleAccessibleNameHtml(el);
  const matched = matchSymbolOnly(visible);
  if (!matched) return;
  emit(buildViolation(el.loc.start.line, el.loc.start.column, matched, subject));
}

/**
 * Walks the button's subtree and returns its visible accessible-name
 * text. Mirrors the WAI name-computation algorithm at the depth this
 * rule needs:
 *
 *   - text nodes contribute their `value`,
 *   - `<img>` with non-empty `alt` contributes the alt text,
 *   - elements with `aria-hidden="true"` or `role="presentation"`/
 *     `"none"` contribute nothing (skipped entirely),
 *   - other elements are recursed into.
 */
function visibleAccessibleNameHtml(root: HtmlElement): string {
  let out = "";
  const visit = (node: HtmlNode): void => {
    if (node.kind === "HtmlText") {
      out += node.value;
      return;
    }
    if (node.kind !== "HtmlElement") return;
    if (isAriaHiddenOrPresentationalHtml(node)) return;
    if (node.tagName.toLowerCase() === "img") {
      const alt = getHtmlAttribute(node, "alt");
      if (alt !== null && alt.trim().length > 0) out += ` ${alt} `;
      return;
    }
    for (const child of node.children) visit(child);
  };
  for (const child of root.children) visit(child);
  return out;
}

function isAriaHiddenOrPresentationalHtml(el: HtmlElement): boolean {
  if (getHtmlAttribute(el, "aria-hidden") === "true") return true;
  const role = (getHtmlAttribute(el, "role") ?? "").toLowerCase();
  return role === "presentation" || role === "none";
}

function hasAccessibleNameOverrideHtml(el: HtmlElement): boolean {
  const ariaLabel = getHtmlAttribute(el, "aria-label");
  if (ariaLabel !== null && ariaLabel.trim().length > 0) return true;
  if (hasHtmlAttribute(el, "aria-labelledby")) return true;
  const title = getHtmlAttribute(el, "title");
  if (title !== null && title.trim().length > 0) return true;
  return false;
}

// ---------------------------------------------------------------------------
// JSX
// ---------------------------------------------------------------------------

function checkJsx(module: TsxModule, wrappersForButton: ReadonlySet<string>, emit: Emit): void {
  const seen = new Set<JsxElement>();
  for (const el of findJsxElementsForTag(module, "button", wrappersForButton)) {
    if (seen.has(el)) continue;
    seen.add(el);
    checkJsxElement(el, el.tagName, emit);
  }
  // role="button" on a non-button JSX element.
  for (const el of walkJsxElements(module)) {
    if (seen.has(el)) continue;
    if (el.tagName === "button" || el.tagName === "input") continue;
    if (getJsxAttributeString(el, "role") !== "button") continue;
    seen.add(el);
    checkJsxElement(el, `${el.tagName} role="button"`, emit);
  }
}

function checkJsxElement(el: JsxElement, subject: string, emit: Emit): void {
  if (getJsxAttributeString(el, "aria-hidden") === "true") return;
  if (hasAccessibleNameOverrideJsx(el)) return;
  // Runtime expression children may carry any name we can't see.
  if (hasJsxExpressionDescendant(el)) return;
  const visible = visibleAccessibleNameJsx(el);
  const matched = matchSymbolOnly(visible);
  if (!matched) return;
  emit(buildViolation(el.loc.start.line, el.loc.start.column, matched, subject));
}

function visibleAccessibleNameJsx(root: JsxElement): string {
  let out = "";
  const visit = (node: JsxNode): void => {
    if (node.kind === "JsxText") {
      out += node.value;
      return;
    }
    if (node.kind !== "JsxElement") return;
    if (isAriaHiddenOrPresentationalJsx(node)) return;
    if (node.tagName.toLowerCase() === "img") {
      const alt = getJsxAttributeString(node, "alt");
      if (alt !== null && alt.trim().length > 0) out += ` ${alt} `;
      return;
    }
    for (const child of node.children) visit(child);
  };
  for (const child of root.children) visit(child);
  return out;
}

function isAriaHiddenOrPresentationalJsx(el: JsxElement): boolean {
  if (getJsxAttributeString(el, "aria-hidden") === "true") return true;
  const role = (getJsxAttributeString(el, "role") ?? "").toLowerCase();
  return role === "presentation" || role === "none";
}

function hasAccessibleNameOverrideJsx(el: JsxElement): boolean {
  const ariaLabel = getJsxAttributeString(el, "aria-label");
  if (ariaLabel !== null && ariaLabel.trim().length > 0) return true;
  if (hasJsxAttribute(el, "aria-labelledby")) return true;
  const title = getJsxAttributeString(el, "title");
  if (title !== null && title.trim().length > 0) return true;
  return false;
}

/**
 * True when any descendant child node is a `JsxExpression`. Walks
 * through wrapper elements because the expression may sit inside a
 * presentational span — `<button><span>{label}</span></button>`.
 * Mirrors the same predicate the `semantics/button-name` rule uses to
 * concede "likely-has-a-name-at-runtime" cases.
 */
function hasJsxExpressionDescendant(element: JsxElement): boolean {
  for (const child of element.children) {
    if (child.kind === "JsxExpression") return true;
    if (child.kind === "JsxElement" && hasJsxExpressionDescendant(child)) return true;
  }
  return false;
}

// ---------------------------------------------------------------------------
// Shared
// ---------------------------------------------------------------------------

/**
 * Returns the matched glyph string IFF the visible text — after entity
 * decoding and whitespace collapse — is one or two codepoints, every
 * one of which is in Unicode punctuation (`\p{P}`) or symbol (`\p{S}`).
 * Returns null for any other shape (empty text, longer text, text
 * containing letters/digits/whitespace alongside the symbol).
 *
 * Codepoint counting uses spread (`[...str]`) so surrogate-pair
 * characters (e.g. emoji) count as one codepoint, not two UTF-16 code
 * units. This is a conservative choice: an emoji-only button is also
 * unnameable, but emoji span the General-Category space irregularly
 * and our tight `\p{P}|\p{S}` predicate intentionally excludes them
 * (`\p{Emoji}` would be a separate decision; surface what we're sure
 * about, not what we're guessing).
 *
 * Mirrors the predicate in `navigation/link-name-only-symbol`. Kept
 * local (no cross-rule import) per the no-cross-rule-dependencies
 * invariant.
 */
function matchSymbolOnly(text: string): string | null {
  let normalized = text;
  for (const [entity, decoded] of Object.entries(NAMED_ENTITY_MAP)) {
    if (normalized.includes(entity)) {
      normalized = normalized.split(entity).join(decoded);
    }
  }
  // Collapse all whitespace (incl. NBSP, U+00A0) to nothing so
  // `<button>  ×  </button>` and `<button>×&nbsp;</button>` reduce to
  // the bare glyph.
  const trimmed = normalized.replace(/\s+/gu, "");
  if (trimmed.length === 0) return null;
  // Codepoint count, not UTF-16 length — see fn doc.
  const codepoints = [...trimmed];
  if (codepoints.length === 0 || codepoints.length > MAX_SYMBOL_NAME_LENGTH) return null;
  for (const cp of codepoints) {
    if (!isPunctuationOrSymbol(cp)) return null;
  }
  return trimmed;
}

function isPunctuationOrSymbol(codepoint: string): boolean {
  // `\p{P}` covers all punctuation (open/close quotes, dashes, brackets,
  // etc.); `\p{S}` covers all symbols (math, currency, arrows, geometric
  // shapes, miscellaneous). Together they exclude `\p{L}` (letters),
  // `\p{N}` (numbers), `\p{M}` (marks), `\p{Z}` (separators — already
  // stripped above), and `\p{C}` (controls/format).
  return /[\p{P}\p{S}]/u.test(codepoint);
}

/**
 * Per-glyph aria-label suggestions. The glyph is the only static signal
 * we have about the button's purpose; this lookup gives the agent a
 * concrete starting candidate rather than a generic "add a name"
 * placeholder. Maps are tight on purpose — unknown glyphs fall back to
 * a generic action-verb list so we never invent a label that doesn't
 * follow from the codepoint's visual convention.
 */
const GLYPH_LABEL_HINTS: Readonly<Record<string, string>> = {
  "×": "Close",
  "✕": "Close",
  "✖": "Close",
  "⨯": "Close",
  "+": "Add",
  "＋": "Add",
  "-": "Remove",
  "−": "Remove",
  "–": "Remove",
  "—": "Remove",
  "?": "Help",
  "？": "Help",
  "!": "Alert",
  "！": "Alert",
  "«": "Previous",
  "‹": "Previous",
  "←": "Previous",
  "↑": "Up",
  "»": "Next",
  "›": "Next",
  "→": "Next",
  "↓": "Down",
  "★": "Favorite",
  "☆": "Favorite",
  "♥": "Favorite",
  "♡": "Favorite",
  "⏵": "Play",
  "▶": "Play",
  "▷": "Play",
  "⏸": "Pause",
  "⏹": "Stop",
  "■": "Stop",
  "⏺": "Record",
  "⏭": "Skip forward",
  "⏮": "Skip back",
  "…": "More options",
  "⋯": "More options",
  "⋮": "More options",
  "≡": "Menu",
  "☰": "Menu",
  "⚙": "Settings",
  "⚙️": "Settings",
};

function suggestedLabelFor(glyph: string): string | null {
  if (glyph in GLYPH_LABEL_HINTS) {
    return GLYPH_LABEL_HINTS[glyph] ?? null;
  }
  return null;
}

function buildViolation(
  line: number,
  column: number,
  glyph: string,
  subject: string,
): {
  severity: "warning";
  location: { filePath: string; line: number; column: number };
  message: string;
  suggestion: string;
} {
  const isPair = [...glyph].length === 2;
  const glyphDescription = isPair ? `the two-character sequence "${glyph}"` : `"${glyph}"`;
  // Per-glyph candidate when we have one; otherwise a generic
  // action-verb list. The hint is additive context — the agent reading
  // the surrounding code picks the right verb.
  const hint = isPair ? null : suggestedLabelFor(glyph);
  const suggestion = hint
    ? `Add an aria-label to the <${subject}> naming the action — the visual convention for ${glyphDescription} is "${hint}" (e.g. \`aria-label="${hint}"\`). Verify the label matches the button's actual behavior; the glyph is a strong visual hint, not a guarantee. Alternative: add a visually-hidden span inside the button (e.g. \`<span class="sr-only">${hint}</span>\`) so the glyph stays as visible decoration but the accessible name carries the words.`
    : `Add an aria-label to the <${subject}> naming the action ` +
      `(e.g. \`aria-label="Close"\` for ×/✕, \`aria-label="Add"\` for +, ` +
      `\`aria-label="Remove"\` for -/−, \`aria-label="Help"\` for ?, ` +
      `\`aria-label="Previous"\` for «/‹/←, \`aria-label="Next"\` for »/›/→, ` +
      `\`aria-label="Play"\` for ⏵/▶, \`aria-label="Pause"\` for ⏸), ` +
      `or add a visually-hidden span inside the button (e.g. \`<span class="sr-only">Close</span>\`) ` +
      `so the glyph stays as visible decoration but the accessible name carries the words.`;
  return {
    severity: "warning",
    location: { filePath: "", line, column },
    message:
      `<${subject}> accessible name is ${glyphDescription} — entirely punctuation/symbol ` +
      "characters. Screen readers announce the codepoint as its Unicode-category name (e.g. " +
      '"multiplication sign" for × or "left-pointing double angle quotation mark" for «) or ' +
      "skip it, leaving the button with no usable action cue.",
    suggestion,
  };
}
